// Parsear query string con grupos nombrados
function parseQueryString(qs) {
  const params = {};
  const patron = /(?<clave>[^=&]+)=(?<valor>[^&]*)/g;

  for (const match of qs.matchAll(patron)) {
    const { clave, valor } = match.groups;
    params[decodeURIComponent(clave)] = decodeURIComponent(valor);
  }

  return params;
}

const qs = 'nombre=Ana&edad=30&ciudad=Bogot%C3%A1&activo=true';
const params = parseQueryString(qs);

console.log(params);
// { nombre: 'Ana', edad: '30', ciudad: 'Bogotá', activo: 'true' }

// Resaltador de sintaxis básico con replace
function resaltarNumeros(codigo) {
  return codigo.replace(/\b\d+\.?\d*\b/g, n => `[NUM:${n}]`);
}

function resaltarStrings(codigo) {
  return codigo.replace(/"([^"]*)"|'([^']*)'/g, (match) => `[STR:${match}]`);
}

function resaltarKeywords(codigo) {
  const kw = ['const', 'let', 'var', 'function', 'return', 'if', 'for'];
  const patron = new RegExp(`\\b(${kw.join('|')})\\b`, 'g');
  return codigo.replace(patron, kw => `[KW:${kw}]`);
}

const codigo = `const x = 42;
function suma(a, b) { return a + b; }
const nombre = 'Ana';`;

console.log(resaltarNumeros(codigo));
console.log(resaltarKeywords(codigo));

