function camelASnake(str) {
  return str.replace(/([A-Z])/g, '_$1').toLowerCase();
}

function snakeACamel(str) {
  return str.replace(/_([a-z])/g, (_, letra) => letra.toUpperCase());
}

function capitalizarPalabras(str) {
  return str.replace(/\b\w/g, c => c.toUpperCase());
}

function eliminarEspaciosExtra(str) {
  return str.trim().replace(/\s+/g, ' ');
}

const r1 = camelASnake('miVariableCamelCase');
const r2 = snakeACamel('mi_variable_snake');
const r3 = capitalizarPalabras('hola mundo cruel');
const r4 = eliminarEspaciosExtra('  texto   con  espacios  ');

console.log(r1, r2, r3, r4);

function formatearTexto(texto, opciones = {}) {
  let resultado = texto;

  if (opciones.sinHtml) {
    resultado = resultado.replace(/<[^>]+>/g, '');
  }

  if (opciones.sinUrl) {
    resultado = resultado.replace(/https?:\/\/[^\s]+/g, '[URL]');
  }

  if (opciones.resaltarNumeros) {
    resultado = resultado.replace(/\b\d+\.?\d*\b/g, n => `**${n}**`);
  }

  if (opciones.normalizarEspacios) {
    resultado = resultado.trim().replace(/\s+/g, ' ');
  }

  return resultado;
}

const entrada = '  <b>Hola</b>  visita https://google.com para   ver 42 ejemplos  ';

const r1 = formatearTexto(entrada, { sinHtml: true });
const r2 = formatearTexto(entrada, { sinUrl: true });
const r3 = formatearTexto(entrada, { sinHtml: true, sinUrl: true, normalizarEspacios: true });
const r4 = formatearTexto('hay 10 y 3.14 valores', { resaltarNumeros: true });

console.log('sinHtml:', r1);
console.log('sinUrl:', r2);
console.log('combinado:', r3);
console.log('numeros:', r4);
